// Package flags implements a cobra-like command line flag parser.
package flags

import (
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

type FlagType int

const (
	TypeBool FlagType = iota
	TypeInt
	TypeString
	TypeFloat
	TypeStrings
	TypeStringArray
)

type Flag struct {
	Long         string
	Short        string // single char, optional
	Type         FlagType
	Description  string
	DefaultStr   string
	DefaultSet   bool
	BoolVal      *bool
	IntVal       *int
	StringVal    *string
	FloatVal     *float64
	StringsVal   *[]string
	StringArrVal *[]string
	Hidden       bool
	stringsOverridden bool
}

type Set struct {
	Name        string
	Flags       []*Flag
	byLong      map[string]*Flag
	byShort     map[string]*Flag
	Args        []string
	Description string
	Version     string
	VersionInfo string // additional info like author
	UsageLine   string
}

func NewSet(name string) *Set {
	return &Set{
		Name:    name,
		byLong:  map[string]*Flag{},
		byShort: map[string]*Flag{},
	}
}

func (s *Set) BoolVar(p *bool, long, short, desc string, def bool) {
	*p = def
	f := &Flag{Long: long, Short: short, Type: TypeBool, Description: desc, BoolVal: p}
	s.add(f)
}

func (s *Set) IntVar(p *int, long, short, desc string, def int) {
	*p = def
	f := &Flag{Long: long, Short: short, Type: TypeInt, Description: desc, IntVal: p, DefaultStr: strconv.Itoa(def), DefaultSet: true}
	s.add(f)
}

func (s *Set) StringVar(p *string, long, short, desc, def string) {
	*p = def
	f := &Flag{Long: long, Short: short, Type: TypeString, Description: desc, StringVal: p, DefaultStr: def, DefaultSet: def != ""}
	s.add(f)
}

func (s *Set) FloatVar(p *float64, long, short, desc string, def float64) {
	*p = def
	d := strconv.FormatFloat(def, 'f', -1, 64)
	f := &Flag{Long: long, Short: short, Type: TypeFloat, Description: desc, FloatVal: p, DefaultStr: d, DefaultSet: true}
	s.add(f)
}

func (s *Set) StringsVar(p *[]string, long, short, desc string, def []string) {
	*p = append([]string{}, def...)
	var d string
	if len(def) > 0 {
		d = "[" + strings.Join(def, ",") + "]"
	} else {
		d = "[]"
	}
	f := &Flag{Long: long, Short: short, Type: TypeStrings, Description: desc, StringsVal: p, DefaultStr: d, DefaultSet: len(def) > 0}
	s.add(f)
}

func (s *Set) StringArrayVar(p *[]string, long, short, desc string, def []string) {
	*p = append([]string{}, def...)
	f := &Flag{Long: long, Short: short, Type: TypeStringArray, Description: desc, StringArrVal: p}
	s.add(f)
}

func (s *Set) add(f *Flag) {
	s.Flags = append(s.Flags, f)
	s.byLong[f.Long] = f
	if f.Short != "" {
		s.byShort[f.Short] = f
	}
}

func (s *Set) Lookup(name string) *Flag {
	if f, ok := s.byLong[name]; ok {
		return f
	}
	return nil
}

// Parse parses args (not including program name).
func (s *Set) Parse(args []string) error {
	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			s.Args = append(s.Args, args[i+1:]...)
			return nil
		}
		if strings.HasPrefix(a, "--") {
			name := a[2:]
			var val string
			hasVal := false
			if idx := strings.Index(name, "="); idx >= 0 {
				val = name[idx+1:]
				name = name[:idx]
				hasVal = true
			}
			f := s.byLong[name]
			if f == nil {
				return fmt.Errorf("unknown flag: --%s", name)
			}
			if f.Type == TypeBool {
				if hasVal {
					b, err := strconv.ParseBool(val)
					if err != nil {
						return fmt.Errorf("invalid boolean value %q for --%s", val, name)
					}
					*f.BoolVal = b
				} else {
					*f.BoolVal = true
				}
				i++
				continue
			}
			if !hasVal {
				if i+1 >= len(args) {
					return fmt.Errorf("flag needs an argument: --%s", name)
				}
				val = args[i+1]
				i++
			}
			if err := s.setFlagValue(f, val); err != nil {
				return err
			}
			i++
			continue
		}
		if strings.HasPrefix(a, "-") && len(a) >= 2 {
			// Short flag - could be combined like -abc but we only support single
			// Could also be -x=val or -x val
			rest := a[1:]
			// handle format -x=val
			var val string
			hasVal := false
			if idx := strings.Index(rest, "="); idx >= 0 {
				val = rest[idx+1:]
				rest = rest[:idx]
				hasVal = true
			}
			// rest may be multiple short flags if they're all boolean
			if len(rest) == 1 {
				f := s.byShort[rest]
				if f == nil {
					return fmt.Errorf("unknown shorthand flag: %q in -%s", rest, rest)
				}
				if f.Type == TypeBool {
					if hasVal {
						b, err := strconv.ParseBool(val)
						if err != nil {
							return fmt.Errorf("invalid boolean value %q for -%s", val, rest)
						}
						*f.BoolVal = b
					} else {
						*f.BoolVal = true
					}
					i++
					continue
				}
				if !hasVal {
					if i+1 >= len(args) {
						return fmt.Errorf("flag needs an argument: -%s", rest)
					}
					val = args[i+1]
					i++
				}
				if err := s.setFlagValue(f, val); err != nil {
					return err
				}
				i++
				continue
			}
			// Combined shorthand - treat all but last as bool; last can take value
			for j, ch := range rest {
				f := s.byShort[string(ch)]
				if f == nil {
					return fmt.Errorf("unknown shorthand flag: %q in -%s", string(ch), rest)
				}
				if f.Type == TypeBool {
					*f.BoolVal = true
					continue
				}
				// Non-bool - consume the rest of the combined string as value, or next arg
				if j < len(rest)-1 {
					val = rest[j+1:]
					hasVal = true
				}
				if !hasVal {
					if i+1 >= len(args) {
						return fmt.Errorf("flag needs an argument: -%s", string(ch))
					}
					val = args[i+1]
					i++
				}
				if err := s.setFlagValue(f, val); err != nil {
					return err
				}
				break
			}
			i++
			continue
		}
		s.Args = append(s.Args, a)
		i++
	}
	return nil
}

func (s *Set) setFlagValue(f *Flag, val string) error {
	switch f.Type {
	case TypeInt:
		v, err := strconv.Atoi(val)
		if err != nil {
			return fmt.Errorf("invalid int %q for --%s", val, f.Long)
		}
		*f.IntVal = v
	case TypeString:
		*f.StringVal = val
	case TypeFloat:
		v, err := strconv.ParseFloat(val, 64)
		if err != nil {
			return fmt.Errorf("invalid float %q for --%s", val, f.Long)
		}
		*f.FloatVal = v
	case TypeStrings:
		// Comma-separated list; replace on each invocation
		if !f.stringsOverridden {
			*f.StringsVal = nil
			f.stringsOverridden = true
		}
		parts := splitCommaRespectingQuotes(val)
		*f.StringsVal = append(*f.StringsVal, parts...)
	case TypeStringArray:
		*f.StringArrVal = append(*f.StringArrVal, val)
	}
	return nil
}

func splitCommaRespectingQuotes(s string) []string {
	var parts []string
	var cur strings.Builder
	inQ := false
	var qChar byte
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inQ {
			if c == qChar {
				inQ = false
				continue
			}
			cur.WriteByte(c)
			continue
		}
		if c == '"' || c == '\'' {
			inQ = true
			qChar = c
			continue
		}
		if c == ',' {
			parts = append(parts, cur.String())
			cur.Reset()
			continue
		}
		cur.WriteByte(c)
	}
	parts = append(parts, cur.String())
	return parts
}

// PrintHelp mimics cobra's help output.
func (s *Set) PrintHelp(out *os.File) {
	if s.Description != "" {
		fmt.Fprintln(out, s.Description)
	}
	if s.Version != "" {
		fmt.Fprintf(out, "Version %s\n", s.Version)
	}
	if s.VersionInfo != "" {
		fmt.Fprintln(out, s.VersionInfo)
	}
	fmt.Fprintln(out)
	fmt.Fprintln(out, "Usage:")
	fmt.Fprintf(out, "  %s\n", s.UsageLine)
	fmt.Fprintln(out)
	fmt.Fprintln(out, "Flags:")
	// Sort by long name case-insensitive to match cobra
	flags := make([]*Flag, 0, len(s.Flags))
	for _, f := range s.Flags {
		if !f.Hidden {
			flags = append(flags, f)
		}
	}
	sort.Slice(flags, func(i, j int) bool {
		a := strings.ToLower(flags[i].Long)
		b := strings.ToLower(flags[j].Long)
		return a < b
	})
	// Compute max prefix width
	type line struct {
		prefix string
		desc   string
	}
	var lines []line
	maxLen := 0
	for _, f := range flags {
		var pfx strings.Builder
		pfx.WriteString("  ")
		if f.Short != "" {
			pfx.WriteString("-")
			pfx.WriteString(f.Short)
			pfx.WriteString(", ")
		} else {
			pfx.WriteString("    ")
		}
		pfx.WriteString("--")
		pfx.WriteString(f.Long)
		if t := typeStr(f); t != "" {
			pfx.WriteString(" ")
			pfx.WriteString(t)
		}
		s := pfx.String()
		if len(s) > maxLen {
			maxLen = len(s)
		}
		d := f.Description
		if f.DefaultSet {
			switch f.Type {
			case TypeString:
				d = d + fmt.Sprintf(" (default %q)", f.DefaultStr)
			default:
				d = d + " (default " + f.DefaultStr + ")"
			}
		}
		lines = append(lines, line{s, d})
	}
	// Pad to col (maxLen + 3)
	pad := maxLen + 3
	for _, l := range lines {
		fmt.Fprint(out, l.prefix)
		// Spaces to pad
		for i := len(l.prefix); i < pad; i++ {
			fmt.Fprint(out, " ")
		}
		fmt.Fprintln(out, l.desc)
	}
}

func typeStr(f *Flag) string {
	switch f.Type {
	case TypeInt:
		return "int"
	case TypeString:
		return "string"
	case TypeFloat:
		return "float"
	case TypeStrings:
		return "strings"
	case TypeStringArray:
		return "stringArray"
	}
	return ""
}
EOF
