		prefix string
		desc   string
	}
	var lines []line
	maxLen := 0
	for _, f := range flags {
		var pfx strings.Builder
		pfx.WriteString("  ")
		if f.Short != "" {
			pfx.WriteString("-")
			pfx.WriteString(f.Short)
			pfx.WriteString(", ")
		} else {
			pfx.WriteString("    ")
		}
		pfx.WriteString("--")
		pfx.WriteString(f.Long)
		if t := typeStr(f); t != "" {
			pfx.WriteString(" ")
			pfx.WriteString(t)
		}
		s := pfx.String()
		if len(s) > maxLen {
			maxLen = len(s)
		}
		d := f.Description
		if f.DefaultSet {
			switch f.Type {
			case TypeString:
				d = d + fmt.Sprintf(" (default %q)", f.DefaultStr)
			default:
				d = d + " (default " + f.DefaultStr + ")"
			}
		}
		lines = append(lines, line{s, d})
	}
	// Pad to col (maxLen + 3)
	pad := maxLen + 3
	for _, l := range lines {
		fmt.Fprint(out, l.prefix)
		// Spaces to pad
		for i := len(l.prefix); i < pad; i++ {
			fmt.Fprint(out, " ")
		}
		fmt.Fprintln(out, l.desc)
	}
}

func typeStr(f *Flag) string {
	switch f.Type {
	case TypeInt:
		return "int"
	case TypeString:
		return "string"
	case TypeFloat:
		return "float"
	case TypeStrings:
		return "strings"
	case TypeStringArray:
		return "stringArray"
	}
	return ""
}
