package lang

import (
	"path/filepath"
	"strings"
)

type DetectIndex struct {
	byExt  map[string][]*LangDef // single extension lookup (many may share)
	byName map[string][]*LangDef // exact filename lookup (case-insensitive)
	all    []LangDef
}

// BuildIndex constructs a case-insensitive detection index from a language list.
// Extensions that look like filenames (contain '.' or match a full filename) are
// registered as name matches.
func BuildIndex(list []LangDef) *DetectIndex {
	idx := &DetectIndex{
		byExt:  map[string][]*LangDef{},
		byName: map[string][]*LangDef{},
		all:    list,
	}
	for i := range list {
		l := &idx.all[i]
		for _, e := range l.Extensions {
			e = strings.ToLower(e)
			// File names starting with dot should be treated as filenames
			// (e.g. .gitignore). Extensions starting with dot should also
			// be treated as filenames.
			if strings.HasPrefix(e, ".") || strings.Contains(e, ".") || strings.Contains(e, "/") {
				// Heuristic: if it has a dot beyond a leading dot, or matches
				// a known filename pattern (like dockerfile), use name matching.
				idx.byName[e] = append(idx.byName[e], l)
				// Also a pure compound like "d.ts" should be registered as byExt with a dot
				if !strings.HasPrefix(e, ".") {
					// Treat as multi-extension suffix match too
					idx.byExt[e] = append(idx.byExt[e], l)
				}
				continue
			}
			idx.byExt[e] = append(idx.byExt[e], l)
		}
	}
	return idx
}

// Detect returns the best language match for a file path, or nil if unknown.
// Prefers: full filename -> longest extension -> single extension.
func (idx *DetectIndex) Detect(path string) *LangDef {
	base := strings.ToLower(filepath.Base(path))
	// exact filename match
	if langs, ok := idx.byName[base]; ok && len(langs) > 0 {
		return langs[0]
	}
	// Try multi-part extensions (e.g. d.ts, blade.php). Walk from the first dot.
	for i := 0; i < len(base); i++ {
		if base[i] == '.' {
			suffix := base[i+1:]
			if langs, ok := idx.byExt[suffix]; ok && len(langs) > 0 {
				return langs[0]
			}
		}
	}
	// Single extension
	ext := filepath.Ext(base)
	if ext != "" && ext[0] == '.' {
		ext = ext[1:]
	}
	if ext != "" {
		if langs, ok := idx.byExt[ext]; ok && len(langs) > 0 {
			return langs[0]
		}
	}
	return nil
}
EOF
