// Package proc counts lines of code in files.
package proc

import (
	"bytes"

	"scc/internal/lang"
)

// FileStats holds per-file stats.
type FileStats struct {
	Path       string
	Name       string
	Ext        string
	Language   string
	Bytes      int64
	Lines      int
	Code       int
	Comment    int
	Blank      int
	Complexity int
	Content    []byte // retained if by-file or for binary detection; nil otherwise
	Binary     bool
	LineLens   []int
}

// Count reads content and returns stats.
func Count(content []byte, def *lang.LangDef) (lines, code, comment, blank, complexity int) {
	// Split into lines (preserve empty last line if file doesn't end with newline).
	// We iterate once, tracking state for block comments and strings.
	lineStart := 0
	inBlock := false
	blockDepth := 0
	var blockEnd string
	i := 0
	for i <= len(content) {
		if i == len(content) || content[i] == '\n' {
			// Process line from lineStart to i (excluding newline)
			line := content[lineStart:i]
			stripLine := bytes.TrimSpace(line)
			if len(stripLine) == 0 {
				if i < len(content) {
					lines++
					blank++
				}
				lineStart = i + 1
				i++
				continue
			}
			if i < len(content) {
				lines++
			} else if len(line) > 0 {
				// last line with no newline
				lines++
			}
			startedInBlock := inBlock
			hasCode := false
			hasComment := false
			hadCodeThisLine := false
			complexityAdded := false

			j := 0
			for j < len(line) {
				ch := line[j]
				if inBlock {
					// Look for nested block start if nested supported
					if def != nil && def.NestedBlocks && len(def.BlockComments) > 0 {
						matched := false
						for _, bc := range def.BlockComments {
							if hasPrefixAt(line, j, bc[0]) {
								blockDepth++
								j += len(bc[0])
								matched = true
								break
							}
						}
						if matched {
							continue
						}
					}
					if blockEnd != "" && hasPrefixAt(line, j, blockEnd) {
						j += len(blockEnd)
						blockDepth--
						if blockDepth <= 0 {
							inBlock = false
							blockEnd = ""
						}
						continue
					}
					j++
					continue
				}
				// Not in block
				if ch == ' ' || ch == '\t' {
					j++
					continue
				}
				// Check for block comment start
				if def != nil {
					matchedBlock := false
					for _, bc := range def.BlockComments {
						if hasPrefixAt(line, j, bc[0]) {
							// Check if whole line is only a block comment (start at beginning of trimmed content)
							if !hadCodeThisLine {
								hasComment = true
							} else {
								// Code followed by block comment on same line
							}
							inBlock = true
							blockDepth = 1
							blockEnd = bc[1]
							j += len(bc[0])
							matchedBlock = true
							break
						}
					}
					if matchedBlock {
						continue
					}
					// Check line comment
					matchedLine := false
					for _, lc := range def.LineComments {
						if hasPrefixAt(line, j, lc) {
							if !hadCodeThisLine {
								hasComment = true
							}
							j = len(line)
							matchedLine = true
							break
						}
					}
					if matchedLine {
						continue
					}
					// Check string
					matchedStr := false
					for _, sp := range def.Strings {
						if hasPrefixAt(line, j, sp[0]) {
							// Consume string until matching end or end of line
							hadCodeThisLine = true
							hasCode = true
							k := j + len(sp[0])
							for k < len(line) {
								if line[k] == '\\' && k+1 < len(line) {
									k += 2
									continue
								}
								if hasPrefixAt(line, k, sp[1]) {
									k += len(sp[1])
									break
								}
								k++
							}
							j = k
							matchedStr = true
							break
						}
					}
					if matchedStr {
						continue
					}
				}
				// Regular code character
				hadCodeThisLine = true
				hasCode = true
				// Complexity check - only at word boundaries start
				if def != nil && !complexityAdded && isWordStart(line, j) {
					for _, k := range def.Complexity {
						if hasPrefixAt(line, j, k) {
							complexity++
							complexityAdded = true
							j += len(k)
							break
						}
					}
					if complexityAdded {
						continue
					}
				}
				j++
			}

			// Classify line
			if !hasCode {
				if startedInBlock || hasComment || inBlock {
					comment++
				} else {
					// No content? should have been caught by blank check
				}
			} else {
				code++
			}

			lineStart = i + 1
		}
		i++
	}
	_ = hasSuffix // appease if not used
	return
}

func hasPrefixAt(b []byte, i int, s string) bool {
	if i+len(s) > len(b) {
		return false
	}
	for k := 0; k < len(s); k++ {
		if b[i+k] != s[k] {
			return false
		}
	}
	return true
}

func isWordStart(b []byte, i int) bool {
	if i == 0 {
		return true
	}
	prev := b[i-1]
	if prev == ' ' || prev == '\t' || prev == '(' || prev == ')' || prev == '{' || prev == '}' || prev == ';' || prev == ',' {
		return true
	}
	return false
}

func hasSuffix(b []byte, s string) bool {
	if len(s) > len(b) {
		return false
	}
	return string(b[len(b)-len(s):]) == s
}
EOF
