// Package fmt implements the output formatters.
package fmt

import (
	gofmt "fmt"
	"io"
	"strconv"
	"strings"
	"unicode/utf8"
)

// Summary is a per-language aggregate.
type Summary struct {
	Name       string
	Files      int
	Lines      int
	Blanks     int
	Comments   int
	Code       int
	Complexity int
	Bytes      int64
	FileList   []FileRow
	ULOC       int
}

type FileRow struct {
	Path       string
	Location   string
	Filename   string
	Extension  string
	Bytes      int64
	Lines      int
	Blanks     int
	Comments   int
	Code       int
	Complexity int
	ULOC       int
}

// Options control output rendering.
type Options struct {
	CI           bool
	Wide         bool
	ByFile       bool
	NoCocomo     bool
	NoSize       bool
	NoHBorder    bool
	NoComplexity bool
	ULOC         bool
	Dryness      bool
	// Sort        string

	// COCOMO display values
	Currency       string
	CostDevelop    float64
	ScheduleMonths float64
	People         float64
	TotalBytes     int64
	SizeUnit       string // e.g. "SI"
	SizeMegabytes  float64
	ModelName      string // organic etc.
	SLOCCount      bool
}

// hrChar returns the horizontal-rule rune/character set.
func (o Options) hrChar() string { if o.CI { return "-" }; return "─" }

// width returns terminal width (fixed 79 like scc default).
func (o Options) width() int {
	if o.Wide {
		if o.ULOC || o.Dryness {
			return 117
		}
		return 109
	}
	if o.ULOC || o.Dryness {
		return 87
	}
	return 79
}

// RenderTabular writes the tabular summary to w.
func RenderTabular(w io.Writer, summaries []Summary, opts Options) {
	hr := strings.Repeat(opts.hrChar(), opts.width())

	gofmt.Fprintln(w, hr)
	// Header row
	gofmt.Fprintln(w, tabularHeader(opts))
	gofmt.Fprintln(w, hr)
	total := Summary{Name: "Total"}
	for _, s := range summaries {
		gofmt.Fprintln(w, tabularRow(s, opts))
		if opts.ByFile {
			gofmt.Fprintln(w, hr)
			for _, f := range s.FileList {
				gofmt.Fprintln(w, tabularFileRow(f, opts))
			}
			gofmt.Fprintln(w, hr)
		}
		total.Files += s.Files
		total.Lines += s.Lines
		total.Blanks += s.Blanks
		total.Comments += s.Comments
		total.Code += s.Code
		total.Complexity += s.Complexity
		total.Bytes += s.Bytes
		total.ULOC += s.ULOC
	}
	if !opts.ByFile {
		gofmt.Fprintln(w, hr)
	}
	gofmt.Fprintln(w, tabularRow(total, opts))
	gofmt.Fprintln(w, hr)
	if !opts.NoCocomo {
		renderCocomo(w, opts)
	}
	if !opts.NoSize {
		gofmt.Fprintf(w, "Processed %d bytes, %s megabytes (%s)\n",
			opts.TotalBytes, formatMegabytes(opts.SizeMegabytes), opts.SizeUnit)
	}
	if !opts.NoCocomo || !opts.NoSize {
		gofmt.Fprintln(w, hr)
	}
}

func formatMegabytes(mb float64) string {
	return strconv.FormatFloat(mb, 'f', 3, 64)
}

func renderCocomo(w io.Writer, opts Options) {
	cur := opts.Currency
	if cur == "" {
		cur = "$"
	}
	gofmt.Fprintf(w, "Estimated Cost to Develop (%s) %s%s\n", opts.ModelName, cur, commaInt(int64(opts.CostDevelop)))
	gofmt.Fprintf(w, "Estimated Schedule Effort (%s) %s months\n", opts.ModelName, strconv.FormatFloat(opts.ScheduleMonths, 'f', 2, 64))
	gofmt.Fprintf(w, "Estimated People Required (%s) %s\n", opts.ModelName, strconv.FormatFloat(opts.People, 'f', 2, 64))
}

func commaInt(n int64) string {
	neg := false
	if n < 0 {
		n = -n
		neg = true
	}
	s := strconv.FormatInt(n, 10)
	if len(s) <= 3 {
		if neg {
			return "-" + s
		}
		return s
	}
	var out []byte
	pre := len(s) % 3
	if pre > 0 {
		out = append(out, s[:pre]...)
		if len(s) > pre {
			out = append(out, ',')
		}
	}
	for i := pre; i < len(s); i += 3 {
		out = append(out, s[i:i+3]...)
		if i+3 < len(s) {
			out = append(out, ',')
		}
	}
	if neg {
		return "-" + string(out)
	}
	return string(out)
}

// Column layout:
//   Language(20 left) Files(5 right) Lines(12 right) Blanks(10 right) Comments(10 right) Code(11 right) Complexity(11 right) [= 79]
//   Wide adds Complexity/Lines(17) and possibly more columns.
func tabularHeader(opts Options) string {
	if opts.Wide {
		return alignL("Language", 30) + alignR("Files", 9) + alignR("Lines", 10) + alignR("Blanks", 9) + alignR("Comments", 9) + alignR("Code", 9) + alignR("Complexity", 11) + alignR("Complexity/Lines", 17) + ulocHeader(opts)
	}
	return alignL("Language", 20) + alignR("Files", 5) + alignR("Lines", 12) + alignR("Blanks", 10) + alignR("Comments", 10) + alignR("Code", 11) + alignR("Complexity", 11) + ulocHeader(opts)
}

func ulocHeader(opts Options) string {
	if opts.Dryness {
		return alignR("DRYness", 11)
	}
	if opts.ULOC {
		return alignR("ULOC", 8)
	}
	return ""
}

func tabularRow(s Summary, opts Options) string {
	if opts.Wide {
		cl := 0.0
		if s.Lines > 0 {
			cl = float64(s.Complexity) / float64(s.Lines) * 100
		}
