					"Complexity":        f.Complexity,
					"WeightedComplexity": 0,
					"Hash":              nil,
					"Binary":            false,
					"Minified":          false,
					"Generated":         false,
					"EndPoint":          0,
					"Uloc":              f.ULOC,
				})
			}
		} else {
			files = []map[string]interface{}{}
