}

func jsonStr(s string) string {
	b, _ := json.Marshal(s)
	return string(b)
}

// RenderJSON2 writes the json2 format with COCOMO fields.
func RenderJSON2(w io.Writer, summaries []Summary, opts Options, byFile bool) {
