// RenderJSON writes the legacy json format.
// Format: [{Name, Bytes, CodeBytes, Lines, Code, Comment, Blank, Complexity, Count, WeightedComplexity, Files, LineLength, ULOC},...]
func RenderJSON(w io.Writer, summaries []Summary, byFile bool) {
	out := make([]map[string]interface{}, 0, len(summaries))
	for _, s := range summaries {
		var files []map[string]interface{}
		if byFile {
			files = make([]map[string]interface{}, 0, len(s.FileList))
			for _, f := range s.FileList {
				files = append(files, map[string]interface{}{
					"Language":          s.Name,
					"PossibleLanguages": []string{s.Name},
					"Filename":          f.Filename,
					"Extension":         f.Extension,
					"Location":          f.Location,
					"Symlocation":       "",
					"Bytes":             f.Bytes,
					"Lines":             f.Lines,
					"Code":              f.Code,
					"Comment":           f.Comments,
					"Blank":             f.Blanks,
					"Complexity":        f.Complexity,
					"WeightedComplexity": 0,
					"Hash":              nil,
					"Binary":            false,
					"Minified":          false,
					"Generated":         false,
					"EndPoint":          0,
					"Uloc":              f.ULOC,
				})
			}
		} else {
			files = []map[string]interface{}{}
		}
		entry := map[string]interface{}{
			"Name":               s.Name,
			"Bytes":              s.Bytes,
			"CodeBytes":          0,
			"Lines":              s.Lines,
			"Code":               s.Code,
			"Comment":            s.Comments,
			"Blank":              s.Blanks,
			"Complexity":         s.Complexity,
			"Count":              s.Files,
			"WeightedComplexity": 0,
			"Files":              files,
			"LineLength":         nil,
			"ULOC":               s.ULOC,
		}
		out = append(out, entry)
	}
	// Match scc output key order by using stable indented format.
	b, _ := json.Marshal(out)
	// Re-emit the bytes as-is; Go's json.Marshal key order matches map iteration
	// which is random. Instead, hand-roll the output.
	_ = b
	// Hand-craft
	writeJSONSummaries(w, summaries, byFile)
}

// writeJSONSummaries writes summaries in scc's fixed key order.
func writeJSONSummaries(w io.Writer, summaries []Summary, byFile bool) {
	gofmt.Fprint(w, "[")
	for i, s := range summaries {
		if i > 0 {
			gofmt.Fprint(w, ",")
		}
		writeSummaryObj(w, s, byFile)
	}
	gofmt.Fprint(w, "]")
}

func writeSummaryObj(w io.Writer, s Summary, byFile bool) {
	gofmt.Fprintf(w, `{"Name":%s,"Bytes":%d,"CodeBytes":0,"Lines":%d,"Code":%d,"Comment":%d,"Blank":%d,"Complexity":%d,"Count":%d,"WeightedComplexity":0,"Files":`,
		jsonStr(s.Name), s.Bytes, s.Lines, s.Code, s.Comments, s.Blanks, s.Complexity, s.Files)
	if byFile {
		gofmt.Fprint(w, "[")
		for i, f := range s.FileList {
			if i > 0 {
				gofmt.Fprint(w, ",")
			}
			gofmt.Fprintf(w, `{"Language":%s,"PossibleLanguages":[%s],"Filename":%s,"Extension":%s,"Location":%s,"Symlocation":"","Bytes":%d,"Lines":%d,"Code":%d,"Comment":%d,"Blank":%d,"Complexity":%d,"WeightedComplexity":0,"Hash":null,"Binary":false,"Minified":false,"Generated":false,"EndPoint":0,"Uloc":%d}`,
				jsonStr(s.Name), jsonStr(s.Name), jsonStr(f.Filename), jsonStr(f.Extension), jsonStr(f.Location),
				f.Bytes, f.Lines, f.Code, f.Comments, f.Blanks, f.Complexity, f.ULOC)
		}
		gofmt.Fprint(w, "]")
	} else {
		gofmt.Fprint(w, "[]")
	}
	gofmt.Fprintf(w, `,"LineLength":null,"ULOC":%d}`, s.ULOC)
}

func jsonStr(s string) string {
