	writeJSONSummaries(w, summaries, byFile)
	gofmt.Fprintf(w, `,"estimatedCost":%s,"estimatedScheduleMonths":%s,"estimatedPeople":%s}`,
		formatFloatFull(opts.CostDevelop), formatFloatFull(opts.ScheduleMonths), formatFloatFull(opts.People))
}

