func printLanguages() {
	for _, l := range lang.AllLangs() {
		fmt.Printf("%s (%s)\n", l.Name, strings.Join(l.Extensions, ","))
	}
}

func run(cfg *config, args []string) {
	start := time.Now()
	if len(args) == 0 {
		args = []string{"."}
	}
	// Verify all paths readable
	for _, p := range args {
		if _, err := os.Stat(p); err != nil {
			if errors.Is(err, fs.ErrNotExist) || os.IsNotExist(err) {
				fmt.Fprintf(os.Stderr, "file or directory could not be read: %s\n", p)
				os.Exit(1)
			}
			fmt.Fprintf(os.Stderr, "file or directory could not be read: %s\n", p)
			os.Exit(1)
		}
	}

	// Build excludes set
	excludeDirs := map[string]bool{}
	for _, d := range cfg.excludeDir {
		excludeDirs[d] = true
	}
	excludeFiles := map[string]bool{}
	for _, f := range cfg.excludeFile {
		excludeFiles[f] = true
	}
	excludeExts := map[string]bool{}
	for _, e := range cfg.excludeExt {
		excludeExts[strings.ToLower(e)] = true
	}
	includeExts := map[string]bool{}
	for _, e := range cfg.includeExt {
		includeExts[strings.ToLower(e)] = true
	}

	// Custom extension remapping via count-as
	countAsMap := parseCountAs(cfg.countAs)

	// Build language index
	langs := lang.AllLangs()
	idx := lang.BuildIndex(langs)

	byLang := map[string]*myfmt.Summary{}
	var totalBytes int64

	processFile := func(path string) {
		info, err := os.Lstat(path)
		if err != nil {
			return
		}
		if info.Mode()&os.ModeSymlink != 0 && !cfg.includeSymlinks {
			return
		}
		basename := filepath.Base(path)
		if excludeFiles[basename] {
			return
		}
		// include / exclude ext logic
		ext := strings.ToLower(filepath.Ext(basename))
		if ext != "" && ext[0] == '.' {
			ext = ext[1:]
		}
		var def *lang.LangDef
		if nm, ok := countAsMap[ext]; ok {
			def = findLang(langs, nm)
		}
		if def == nil {
			def = idx.Detect(path)
		}
		if def == nil {
			return
		}
		detectedExt := ext
		if detectedExt == "" {
			detectedExt = strings.ToLower(basename)
		}
		if len(includeExts) > 0 && !includeExts[detectedExt] {
			return
		}
		if excludeExts[detectedExt] {
			return
		}
		content, err := os.ReadFile(path)
		if err != nil {
			return
		}
		lines, code, comment, blank, complexity := proc.Count(content, def)
		if cfg.noComplexity {
			complexity = 0
		}
		s, ok := byLang[def.Name]
		if !ok {
			s = &myfmt.Summary{Name: def.Name}
			byLang[def.Name] = s
		}
		s.Files++
		s.Lines += lines
		s.Code += code
		s.Comments += comment
		s.Blanks += blank
		s.Complexity += complexity
		s.Bytes += int64(len(content))
		totalBytes += int64(len(content))
		absPath := path
		if ap, err := filepath.Abs(path); err == nil {
			absPath = ap
		}
		s.FileList = append(s.FileList, myfmt.FileRow{
			Path:       path,
			Location:   absPath,
			Filename:   basename,
			Extension:  ext,
			Bytes:      int64(len(content)),
			Lines:      lines,
			Blanks:     blank,
			Comments:   comment,
			Code:       code,
			Complexity: complexity,
		})
	}

	// Walk
	for _, p := range args {
		info, err := os.Stat(p)
		if err != nil {
			continue
		}
		if info.IsDir() {
			_ = filepath.WalkDir(p, func(path string, d fs.DirEntry, err error) error {
				if err != nil {
					return nil
				}
				if d.IsDir() {
					if excludeDirs[d.Name()] {
						return fs.SkipDir
					}
					return nil
				}
				processFile(path)
				return nil
			})
		} else {
			processFile(p)
		}
	}

	// Sort summaries
	summaries := make([]myfmt.Summary, 0, len(byLang))
	for _, s := range byLang {
		summaries = append(summaries, *s)
	}
	sortSummaries(summaries, cfg.sort)

	// Build options for render
	opts := myfmt.Options{
		CI:           cfg.ci,
		Wide:         cfg.wide,
		ByFile:       cfg.byFile,
		NoCocomo:     cfg.noCocomo,
		NoSize:       cfg.noSize,
		NoHBorder:    cfg.noHborder,
		NoComplexity: cfg.noComplexity,
		ULOC:         cfg.uloc,
		Dryness:      cfg.dryness,
		Currency:     cfg.currencySymbol,
		TotalBytes:   totalBytes,
		ModelName:    cfg.cocomoType,
	}
	opts.SizeUnit = strings.ToUpper(cfg.sizeUnit)
	if opts.SizeUnit == "SI" {
		opts.SizeMegabytes = float64(totalBytes) / 1e6
	} else {
		opts.SizeMegabytes = float64(totalBytes) / 1e6
	}

	// COCOMO
	var totalCode int
	for _, s := range summaries {
		totalCode += s.Code
	}
	opts.CostDevelop, opts.ScheduleMonths, opts.People = cocomo(totalCode, cfg)

	// Output
	var out io.Writer = os.Stdout
	if cfg.output != "" {
		f, err := os.Create(cfg.output)
		if err != nil {
			fmt.Fprintf(os.Stderr, "cannot create output: %s\n", err)
			os.Exit(1)
		}
		defer f.Close()
		out = f
	}

	switch cfg.format {
	case "tabular":
		myfmt.RenderTabular(out, summaries, opts)
	case "wide":
		opts.Wide = true
		myfmt.RenderTabular(out, summaries, opts)
	case "json":
		myfmt.RenderJSON(out, summaries, cfg.byFile)
	case "json2":
		myfmt.RenderJSON2(out, summaries, opts, cfg.byFile)
	case "csv":
		myfmt.RenderCSV(out, summaries)
	case "csv-stream":
		myfmt.RenderCSVStreamHeader(out)
		for _, s := range summaries {
			for _, f := range s.FileList {
				myfmt.RenderCSVStreamRow(out, s.Name, f)
			}
		}
	case "cloc-yaml":
		myfmt.RenderClocYAML(out, summaries, opts, time.Since(start).Seconds(), Version)
	default:
		myfmt.RenderTabular(out, summaries, opts)
	}

	if cfg.output != "" {
		fmt.Printf("results written to %s\n", cfg.output)
	}
}

func parseCountAs(s string) map[string]string {
	m := map[string]string{}
	if s == "" {
		return m
	}
	// format: ext:lang,ext2:lang2
	parts := strings.Split(s, ",")
	for _, p := range parts {
		i := strings.Index(p, ":")
		if i < 0 {
			continue
		}
		e := strings.ToLower(strings.TrimSpace(p[:i]))
		v := strings.Trim(strings.TrimSpace(p[i+1:]), "\"'")
		m[e] = v
	}
	return m
}

func findLang(list []lang.LangDef, name string) *lang.LangDef {
	ln := strings.ToLower(name)
	for i := range list {
		if strings.ToLower(list[i].Name) == ln {
			return &list[i]
		}
	}
	return nil
}

func sortSummaries(sums []myfmt.Summary, col string) {
	less := func(a, b myfmt.Summary) bool { return a.Files > b.Files }
	switch strings.ToLower(col) {
	case "files":
		less = func(a, b myfmt.Summary) bool { return a.Files > b.Files }
	case "name":
		less = func(a, b myfmt.Summary) bool { return a.Name < b.Name }
	case "lines":
		less = func(a, b myfmt.Summary) bool { return a.Lines > b.Lines }
	case "code":
		less = func(a, b myfmt.Summary) bool { return a.Code > b.Code }
	case "blanks":
		less = func(a, b myfmt.Summary) bool { return a.Blanks > b.Blanks }
	case "comments":
		less = func(a, b myfmt.Summary) bool { return a.Comments > b.Comments }
	case "complexity":
		less = func(a, b myfmt.Summary) bool { return a.Complexity > b.Complexity }
	}
	sort.SliceStable(sums, func(i, j int) bool {
		if less(sums[i], sums[j]) {
			return true
		}
		if less(sums[j], sums[i]) {
			return false
		}
		return sums[i].Name < sums[j].Name
	})
}

// cocomo returns estimated cost, schedule months, people for given total code lines.
func cocomo(code int, cfg *config) (float64, float64, float64) {
	a, b, c, d := cocomoModel(cfg.cocomoType)
	kloc := float64(code) / 1000.0
	effort := a * math.Pow(kloc, b) * cfg.eaf
	months := c * math.Pow(effort, d)
	people := 0.0
	if months > 0 {
		people = effort / months
	}
	cost := effort * (float64(cfg.avgWage) / 12.0) * cfg.overhead
	return cost, months, people
}

func cocomoModel(name string) (a, b, c, d float64) {
	switch strings.ToLower(name) {
	case "organic":
		return 2.4, 1.05, 2.5, 0.38
	case "semi-detached":
		return 3.0, 1.12, 2.5, 0.35
	case "embedded":
		return 3.6, 1.20, 2.5, 0.32
	}
	// custom,a,b,c,d
	if strings.HasPrefix(name, "custom,") {
		parts := strings.Split(name[len("custom,"):], ",")
		if len(parts) == 4 {
			fv := make([]float64, 4)
			for i, p := range parts {
				v := 0.0
				fmt.Sscanf(p, "%f", &v)
				fv[i] = v
			}
			return fv[0], fv[1], fv[2], fv[3]
		}
	}
	return 2.4, 1.05, 2.5, 0.38
}
