package lang

import (
	"path/filepath"
	"strings"
)

type DetectIndex struct {
	byExt  map[string][]*LangDef
	byName map[string][]*LangDef
	all    []LangDef
}

// BuildIndex constructs a case-insensitive detection index from a language list.
func BuildIndex(list []LangDef) *DetectIndex {
	idx := &DetectIndex{
		byExt:  map[string][]*LangDef{},
		byName: map[string][]*LangDef{},
		all:    list,
	}
	for i := range list {
		l := &idx.all[i]
		for _, e := range l.Extensions {
			e = strings.ToLower(e)
			// Files that look like dotfiles (start with dot) are pure filename matches.
			if strings.HasPrefix(e, ".") {
				idx.byName[e] = append(idx.byName[e], l)
				continue
			}
			// Contains a dot (and not leading) -> try as multi-extension suffix
			// e.g. d.ts, blade.php, build.bazel -- could be suffix OR exact filename.
			if strings.Contains(e, ".") {
				// Register both as byExt suffix and byName filename
				idx.byExt[e] = append(idx.byExt[e], l)
				idx.byName[e] = append(idx.byName[e], l)
				continue
			}
			// Plain token - could be an extension (go, py) or a filename (dockerfile, makefile).
			idx.byExt[e] = append(idx.byExt[e], l)
			idx.byName[e] = append(idx.byName[e], l)
		}
	}
	return idx
}

// Detect returns the best language match for a file path, or nil if unknown.
// Prefers: full filename -> longest extension -> single extension.
func (idx *DetectIndex) Detect(path string) *LangDef {
	base := strings.ToLower(filepath.Base(path))
	// exact filename match
	if langs, ok := idx.byName[base]; ok && len(langs) > 0 {
		return langs[0]
	}
	// Multi-part extensions
	for i := 0; i < len(base); i++ {
		if base[i] == '.' {
			suffix := base[i+1:]
			if langs, ok := idx.byExt[suffix]; ok && len(langs) > 0 {
				return langs[0]
			}
		}
	}
	// Single extension
	ext := filepath.Ext(base)
	if ext != "" && ext[0] == '.' {
		ext = ext[1:]
	}
	if ext != "" {
		if langs, ok := idx.byExt[ext]; ok && len(langs) > 0 {
			return langs[0]
		}
	}
	return nil
}
