// Package proc counts lines of code in files.
package proc

import (
	"bytes"

	"scc/internal/lang"
)

// FileStats holds per-file stats.
type FileStats struct {
	Path       string
	Name       string
	Ext        string
	Language   string
	Bytes      int64
	Lines      int
	Code       int
	Comment    int
	Blank      int
	Complexity int
	Content    []byte
	Binary     bool
	LineLens   []int
}

// Count counts stats for the given content with the language definition.
// Returns: lines (non-empty + empty counted), code, comment, blank, complexity.
func Count(content []byte, def *lang.LangDef) (lines, code, comment, blank, complexity int) {
	lineStart := 0
	inBlock := false
	blockDepth := 0
	var blockEnd string

	i := 0
	for {
		end := i == len(content)
		if end || content[i] == '\n' {
			// Process line content [lineStart:i]
			line := content[lineStart:i]
			if len(line) == 0 {
				if !end {
					lines++
					blank++
					lineStart = i + 1
					i++
					continue
				}
				break
			}
			// non-empty line: count it
			lines++
			trim := bytes.TrimSpace(line)
			if len(trim) == 0 {
				blank++
				lineStart = i + 1
				i++
				continue
			}

			startedInBlock := inBlock
			var hasCode, hasComment bool
			hadCodeThisLine := false

			j := 0
			for j < len(line) {
				ch := line[j]
				if inBlock {
					if def != nil && def.NestedBlocks {
						matched := false
						for _, bc := range def.BlockComments {
							if hasPrefixAt(line, j, bc[0]) {
								blockDepth++
								j += len(bc[0])
								matched = true
								break
							}
						}
						if matched {
							continue
						}
					}
					if blockEnd != "" && hasPrefixAt(line, j, blockEnd) {
						j += len(blockEnd)
						blockDepth--
						if blockDepth <= 0 {
							inBlock = false
							blockEnd = ""
						}
						continue
					}
					j++
					continue
				}
				// not in block
				if ch == ' ' || ch == '\t' {
					j++
					continue
				}

				if def != nil {
					// block comment start
					matched := false
					for _, bc := range def.BlockComments {
						if hasPrefixAt(line, j, bc[0]) {
							if !hadCodeThisLine {
								hasComment = true
							}
							inBlock = true
							blockDepth = 1
							blockEnd = bc[1]
							j += len(bc[0])
							matched = true
							break
						}
					}
					if matched {
						continue
					}
					// line comment
					for _, lc := range def.LineComments {
						if hasPrefixAt(line, j, lc) {
							if !hadCodeThisLine {
								hasComment = true
							}
							j = len(line)
							matched = true
							break
						}
					}
					if matched {
						continue
					}
					// string literal
					for _, sp := range def.Strings {
						if hasPrefixAt(line, j, sp[0]) {
							hadCodeThisLine = true
							hasCode = true
							k := j + len(sp[0])
							for k < len(line) {
								if line[k] == '\\' && k+1 < len(line) && sp[0] != "'" {
									k += 2
									continue
								}
								if hasPrefixAt(line, k, sp[1]) {
									k += len(sp[1])
									break
								}
								k++
							}
							j = k
							matched = true
							break
						}
					}
					if matched {
						continue
					}
					// complexity keyword - count every occurrence when at word start
					if len(def.Complexity) > 0 && isWordStart(line, j) {
						for _, k := range def.Complexity {
							if hasPrefixAt(line, j, k) {
								complexity++
								j += len(k)
								matched = true
								break
							}
						}
						if matched {
							hadCodeThisLine = true
							hasCode = true
							continue
						}
					}
				}
				hadCodeThisLine = true
				hasCode = true
				j++
			}

			if !hasCode {
				if startedInBlock || hasComment || inBlock {
					comment++
				}
			} else {
				code++
			}

			if end {
				break
			}
			lineStart = i + 1
		}
		if end {
			break
		}
		i++
	}
	return
}

func hasPrefixAt(b []byte, i int, s string) bool {
	if i+len(s) > len(b) {
		return false
	}
	for k := 0; k < len(s); k++ {
		if b[i+k] != s[k] {
			return false
		}
	}
	return true
}

func isWordStart(b []byte, i int) bool {
	if i == 0 {
		return true
	}
	prev := b[i-1]
	switch prev {
	case ' ', '\t', '(', ')', '{', '}', '[', ']', ';', ',':
		return true
	}
	return false
}
