// Package proc counts lines of code in files.
package proc

import (
	"bytes"

	"scc/internal/lang"
)

// FileStats holds per-file stats.
type FileStats struct {
	Path       string
	Name       string
	Ext        string
	Language   string
	Bytes      int64
	Lines      int
	Code       int
	Comment    int
	Blank      int
	Complexity int
	Content    []byte
	Binary     bool
	LineLens   []int
}

// Count counts stats for the given content with the language definition.
func Count(content []byte, def *lang.LangDef) (lines, code, comment, blank, complexity int) {
	lineStart := 0
	inBlock := false
	blockDepth := 0
	var blockEnd string
	inStr := false
	var strEnd string
	escape := false

	i := 0
	for {
		end := i == len(content)
		if end || content[i] == '\n' {
			line := content[lineStart:i]
			hasContent := len(line) > 0
			isBlank := len(bytes.TrimSpace(line)) == 0
			if !end {
				lines++
			} else if hasContent {
				lines++
			}
			if isBlank && hasContent {
				blank++
				lineStart = i + 1
				i++
				continue
			}
			if !hasContent && end {
				// EOF and last line empty
				break
			}
			if !hasContent {
				// blank line already counted above if had \n
				lineStart = i + 1
				i++
				continue
			}

			startedInBlock := inBlock
			startedInStr := inStr
			var hasCode, hasComment bool
			hadCodeThisLine := false

			j := 0
			for j < len(line) {
				ch := line[j]
				if inBlock {
					if def != nil && def.NestedBlocks {
						matched := false
						for _, bc := range def.BlockComments {
							if hasPrefixAt(line, j, bc[0]) {
								blockDepth++
								j += len(bc[0])
								matched = true
								break
							}
						}
						if matched {
							continue
						}
					}
					if blockEnd != "" && hasPrefixAt(line, j, blockEnd) {
						j += len(blockEnd)
						blockDepth--
						if blockDepth <= 0 {
							inBlock = false
							blockEnd = ""
						}
						continue
					}
					j++
					continue
				}
				if inStr {
					if escape {
						escape = false
						j++
						continue
					}
					if ch == '\\' {
						escape = true
						j++
						continue
					}
					if strEnd != "" && hasPrefixAt(line, j, strEnd) {
						j += len(strEnd)
						inStr = false
						strEnd = ""
						continue
					}
					j++
					continue
				}
				if ch == ' ' || ch == '\t' {
					j++
					continue
				}
				if def != nil {
					matched := false
					for _, bc := range def.BlockComments {
						if hasPrefixAt(line, j, bc[0]) {
							if !hadCodeThisLine {
								hasComment = true
							}
							inBlock = true
							blockDepth = 1
							blockEnd = bc[1]
							j += len(bc[0])
							matched = true
							break
						}
					}
					if matched {
						continue
					}
					for _, lc := range def.LineComments {
						if hasPrefixAt(line, j, lc) {
							if !hadCodeThisLine {
								hasComment = true
							}
							j = len(line)
