	"bytes"

	"scc/internal/lang"
)

// FileStats holds per-file stats.
type FileStats struct {
	Path       string
	Name       string
	Ext        string
	Language   string
	Bytes      int64
	Lines      int
	Code       int
	Comment    int
	Blank      int
	Complexity int
	Content    []byte
	Binary     bool
	LineLens   []int
}

// Count counts stats for the given content with the language definition.
// String and block comment state persists across lines.
func Count(content []byte, def *lang.LangDef) (lines, code, comment, blank, complexity int) {
	inBlock := false
	blockDepth := 0
	var blockEnd string
	inStr := false
	var strEnd string
	escape := false

	// Split content into lines, ignoring trailing empty newline.
	lineStart := 0
	for idx := 0; idx <= len(content); idx++ {
		if idx < len(content) && content[idx] != '\n' {
			continue
		}
		// line bytes
		line := content[lineStart:idx]
		if idx == len(content) && idx == lineStart {
			// no trailing partial line
			break
		}
		lines++

		trim := bytes.TrimSpace(line)
		if len(trim) == 0 {
			blank++
			lineStart = idx + 1
			continue
		}

		startedInBlock := inBlock
		startedInStr := inStr
		var hasCode, hasComment bool
		hadCodeThisLine := false

		j := 0
		for j < len(line) {
			ch := line[j]
			if inBlock {
				if def != nil && def.NestedBlocks {
					matched := false
					for _, bc := range def.BlockComments {
						if hasPrefixAt(line, j, bc[0]) {
							blockDepth++
							j += len(bc[0])
							matched = true
							break
						}
					}
					if matched {
						continue
					}
				}
				if blockEnd != "" && hasPrefixAt(line, j, blockEnd) {
					j += len(blockEnd)
					blockDepth--
					if blockDepth <= 0 {
						inBlock = false
						blockEnd = ""
					}
					continue
				}
				j++
				continue
			}
			if inStr {
				if escape {
					escape = false
					j++
					continue
				}
				if ch == '\\' {
					escape = true
					j++
					continue
				}
				if strEnd != "" && hasPrefixAt(line, j, strEnd) {
					j += len(strEnd)
					inStr = false
					strEnd = ""
					continue
				}
				j++
				continue
			}
			if ch == ' ' || ch == '\t' {
				j++
				continue
			}
			if def != nil {
				matched := false
				for _, bc := range def.BlockComments {
					if hasPrefixAt(line, j, bc[0]) {
						if !hadCodeThisLine {
							hasComment = true
						}
						inBlock = true
						blockDepth = 1
						blockEnd = bc[1]
						j += len(bc[0])
						matched = true
						break
					}
				}
				if matched {
					continue
				}
				for _, lc := range def.LineComments {
					if hasPrefixAt(line, j, lc) {
						if !hadCodeThisLine {
							hasComment = true
						}
						j = len(line)
						matched = true
						break
					}
				}
				if matched {
					continue
				}
				for _, sp := range def.Strings {
					if hasPrefixAt(line, j, sp[0]) {
						hadCodeThisLine = true
						hasCode = true
						inStr = true
						strEnd = sp[1]
						j += len(sp[0])
						matched = true
						break
					}
				}
				if matched {
					continue
				}
				if len(def.Complexity) > 0 && isWordStart(line, j) {
					for _, k := range def.Complexity {
						if hasPrefixAt(line, j, k) {
							complexity++
							j += len(k)
							matched = true
							break
						}
					}
					if matched {
						hadCodeThisLine = true
						hasCode = true
						continue
					}
				}
			}
			hadCodeThisLine = true
			hasCode = true
			j++
		}

		if !hasCode {
			if startedInBlock || hasComment || inBlock || startedInStr || inStr {
				comment++
			} else {
				// no classification; count as blank? scc seems to count as blank
				blank++
			}
		} else {
			code++
		}
		lineStart = idx + 1
	}
	return
}

func hasPrefixAt(b []byte, i int, s string) bool {
	if i+len(s) > len(b) {
		return false
	}
	for k := 0; k < len(s); k++ {
		if b[i+k] != s[k] {
			return false
		}
	}
	return true
}

func isWordStart(b []byte, i int) bool {
	if i == 0 {
		return true
	}
	prev := b[i-1]
	switch prev {
	case ' ', '\t', '(', ')', '{', '}', '[', ']', ';', ',':
		return true
	}
	return false
}
